# Workflow: abby_soil_moisture_fungi
# Function: align_and_report

import math
import os
import tempfile

import matplotlib

matplotlib.use("Agg")
import matplotlib.dates as mdates  # noqa: E402
import matplotlib.pyplot as plt  # noqa: E402
import pandas as pd  # noqa: E402

SOIL_REQUIRED = [
    "month", "mean_soil_moisture", "n_measurements", "depth_used_cm",
    "units", "site_code", "latitude", "longitude", "radius_m",
]
FUNGI_REQUIRED = ["month", "fungi_count"]
SUMMARY_COLUMNS = [
    "month", "fungi_count", "mean_soil_moisture", "n_measurements", "depth_used_cm",
    "units", "site_code", "latitude", "longitude", "radius_m",
]


def _fail(msg, exc_type=ValueError):
    faasr_log(msg)
    raise exc_type(msg)


def _normalize_month(series):
    parsed = pd.to_datetime(series.astype(str).str.strip().str[:7], format="%Y-%m", errors="coerce")
    return parsed


def _pearson(x, y):
    n = len(x)
    mx = sum(x) / n
    my = sum(y) / n
    sxy = sum((a - mx) * (b - my) for a, b in zip(x, y))
    sxx = sum((a - mx) ** 2 for a in x)
    syy = sum((b - my) ** 2 for b in y)
    if sxx == 0 or syy == 0:
        return None
    return sxy / math.sqrt(sxx * syy)


def _spearman(x, y):
    rx = pd.Series(x).rank(method="average").tolist()
    ry = pd.Series(y).rank(method="average").tolist()
    return _pearson(rx, ry)


def _fmt_depths(depths):
    uniq = sorted(set(round(float(d), 1) for d in depths if pd.notna(d)))
    if not uniq:
        return "unknown depth"
    if len(uniq) == 1:
        return f"{uniq[0]:g} cm depth"
    return f"{uniq[0]:g}-{uniq[-1]:g} cm depth"


def align_and_report(folder: str, input1: str, input2: str, output1: str, output2: str) -> None:
    workdir = tempfile.mkdtemp(prefix="align_report_")
    soil_path = os.path.join(workdir, "monthly_soil_moisture.csv")
    fungi_path = os.path.join(workdir, "monthly_fungi_counts.csv")
    faasr_get_file(local_file=soil_path, remote_folder=folder, remote_file=input1)
    faasr_get_file(local_file=fungi_path, remote_folder=folder, remote_file=input2)

    # --- soil moisture ---
    try:
        soil = pd.read_csv(soil_path, dtype={"month": str, "units": str, "site_code": str})
    except Exception as exc:
        _fail(f"Could not read soil moisture file {input1}: {exc}")
    missing = [c for c in SOIL_REQUIRED if c not in soil.columns]
    if missing:
        _fail(f"{input1} is missing required columns {missing}; found {list(soil.columns)}")
    if soil.empty:
        _fail(f"{input1} contains no monthly soil moisture rows")
    soil["month_dt"] = _normalize_month(soil["month"])
    bad = soil["month_dt"].isna().sum()
    if bad:
        _fail(f"{input1} has {bad} rows with an unparseable month (expected YYYY-MM)")
    soil["mean_soil_moisture"] = pd.to_numeric(soil["mean_soil_moisture"], errors="coerce")
    soil = soil[soil["mean_soil_moisture"].notna()].copy()
    if soil.empty:
        _fail(f"{input1} has no valid mean_soil_moisture values")
    if soil["month_dt"].duplicated().any():
        _fail(f"{input1} has duplicate months: "
              f"{sorted(soil.loc[soil['month_dt'].duplicated(), 'month'].tolist())}")

    # --- fungi counts ---
    try:
        fungi = pd.read_csv(fungi_path, dtype={"month": str})
    except pd.errors.EmptyDataError:
        _fail(f"{input2} is empty (no header); expected columns {FUNGI_REQUIRED}")
    except Exception as exc:
        _fail(f"Could not read fungi count file {input2}: {exc}")
    missing = [c for c in FUNGI_REQUIRED if c not in fungi.columns]
    if missing:
        _fail(f"{input2} is missing required columns {missing}; found {list(fungi.columns)}")
    fungi["month_dt"] = _normalize_month(fungi["month"])
    bad = fungi["month_dt"].isna().sum()
    if bad:
        _fail(f"{input2} has {bad} rows with an unparseable month (expected YYYY-MM)")
    fungi["fungi_count"] = pd.to_numeric(fungi["fungi_count"], errors="coerce")
    if fungi["fungi_count"].isna().any():
        _fail(f"{input2} has non-numeric fungi_count values")
    fungi = fungi.groupby("month_dt", as_index=False)["fungi_count"].sum()

    # --- left join on soil-moisture months ---
    merged = soil.merge(fungi, on="month_dt", how="left")
    merged["fungi_count"] = merged["fungi_count"].fillna(0).astype(int)
    merged = merged.sort_values("month_dt").reset_index(drop=True)
    merged["month"] = merged["month_dt"].dt.strftime("%Y-%m")

    soil_months = set(merged["month_dt"])
    unused = fungi[~fungi["month_dt"].isin(soil_months)]
    faasr_log(
        f"Aligned {len(merged)} soil-moisture months ({merged['month'].iloc[0]} to {merged['month'].iloc[-1]}); "
        f"{int((merged['fungi_count'] > 0).sum())} months with fungi observations, "
        f"{int(merged['fungi_count'].sum())} observations in period; "
        f"{len(unused)} fungi months ({int(unused['fungi_count'].sum())} observations) outside the period not used"
    )

    # --- correlations ---
    x = merged["mean_soil_moisture"].astype(float).tolist()
    y = merged["fungi_count"].astype(float).tolist()
    pearson = spearman = None
    if len(merged) >= 3:
        pearson = _pearson(x, y)
        spearman = _spearman(x, y)
    fmt = lambda v: "empty (undefined)" if v is None else f"{v:.4f}"  # noqa: E731
    if len(merged) < 3:
        faasr_log(f"Only {len(merged)} aligned months (<3); correlations left empty")
    else:
        faasr_log(f"Correlation over {len(merged)} aligned months: Pearson r = {fmt(pearson)}, "
                  f"Spearman rho = {fmt(spearman)}")

    # --- summary table ---
    summary = merged[SUMMARY_COLUMNS]
    summary_path = os.path.join(workdir, "abby_monthly_summary.csv")
    summary.to_csv(summary_path, index=False)

    # --- plot ---
    site_code = str(merged["site_code"].iloc[0])
    lat = float(merged["latitude"].iloc[0])
    lon = float(merged["longitude"].iloc[0])
    radius = merged["radius_m"].iloc[0]
    radius_txt = f"{float(radius):g}"
    units = str(merged["units"].iloc[0])
    depth_txt = _fmt_depths(merged["depth_used_cm"].tolist())

    fig, ax1 = plt.subplots(figsize=(13, 6))
    bars = ax1.bar(merged["month_dt"], merged["fungi_count"], width=20, align="center",
                   color="#c58b3a", alpha=0.75, label="iNaturalist fungi observations (count/month)")
    ax1.set_xlabel("Month")
    ax1.set_ylabel("Monthly fungi observation count")
    ax1.set_ylim(bottom=0)
    ax2 = ax1.twinx()
    # Reindex to a continuous monthly range so the line breaks across months without data
    full_idx = pd.date_range(merged["month_dt"].min(), merged["month_dt"].max(), freq="MS")
    line_series = merged.set_index("month_dt")["mean_soil_moisture"].reindex(full_idx)
    (line,) = ax2.plot(line_series.index, line_series.values, color="#1f5fa8",
                       marker="o", markersize=4, linewidth=1.5,
                       label=f"Mean soil moisture ({units}, {depth_txt})")
    ax2.set_ylabel(f"Mean soil moisture ({units}), {depth_txt}")
    ax1.xaxis.set_major_locator(mdates.AutoDateLocator())
    ax1.xaxis.set_major_formatter(mdates.DateFormatter("%Y-%m"))
    fig.autofmt_xdate()
    ax1.legend([bars, line], [bars.get_label(), line.get_label()], loc="upper left")
    ax1.set_title(
        f"NEON {site_code} (Abby Road, WA): monthly soil moisture vs. iNaturalist fungi observations\n"
        f"within {radius_txt} m radius of ({lat:.6f}, {lon:.6f})"
    )
    fig.tight_layout()
    plot_path = os.path.join(workdir, "abby_soil_moisture_fungi_plot.png")
    fig.savefig(plot_path, dpi=150)
    plt.close(fig)

    faasr_put_file(local_file=plot_path, remote_folder=folder, remote_file=output1)
    faasr_put_file(local_file=summary_path, remote_folder=folder, remote_file=output2)
    faasr_log(f"Wrote {output1} and {output2} ({len(summary)} rows)")
